package it.pulse.workout.data

import java.text.Normalizer

data class LibraryExercise(val id: String, val name: String, val muscle: String,
    val equipment: String, val brand: String = "", val model: String = "", val timed: Boolean = false) {
    fun asExercise(template: Exercise? = null): Exercise = Exercise(
        id = id, name = name, muscle = muscle,
        sets = template?.sets ?: 3,
        target = if (template != null && template.timeBased == timed) template.target else if (timed) "30–60" else "8–12",
        restSeconds = template?.restSeconds ?: 90, equipment = equipment,
        rir = template?.rir ?: "1–3", optional = template?.optional ?: false,
        timeBased = timed, primaryMuscles = CustomPlanRules.muscleIds(muscle),
        note = if (brand == "Panatta") "Modello $model. Carichi separati dalle altre macchine: usa sempre la stessa convenzione totale/per lato."
            else if (equipment == "Manubri") "Registra il carico per manubrio in modo coerente."
            else "Confronta i carichi solo sullo stesso attrezzo e con la stessa regolazione."
    )
}

