    val muscles = all.map { it.muscle }.distinct()
    val equipment = all.map { it.equipment }.distinct().sorted()
    fun search(query: String, muscle: String? = null, equipment: String? = null,
        panattaOnly: Boolean = false): List<LibraryExercise> {
        val terms = normalized(query).split(Regex("\\s+")).filter { it.isNotBlank() }
        return all.filter { item ->
            (muscle == null || item.muscle == muscle) &&
            (equipment == null || item.equipment == equipment) &&
            (!panattaOnly || item.brand == "Panatta") &&
            terms.all { it in normalized("${item.name} ${item.muscle} ${item.equipment} ${item.model}") }
        }
    }
    fun alternatives(current: Exercise, day: WorkoutDay): List<LibraryExercise> {
        val muscleIds = ExerciseMuscleMapping.forExercise(current).first.toSet()
        return all.filter { candidate ->
            candidate.id != current.id && day.exercises.none { it.id == candidate.id } &&
                candidate.asExercise().primaryMuscles.any { it in muscleIds }
        }.sortedByDescending { it.brand == "Panatta" }
    }
